package com.chx.notification.application;
import com.chx.notification.api.EventEnvelope; import com.chx.notification.domain.*; import com.chx.notification.infra.*; import java.time.*; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService { private final ProcessedEventRepository processed; private final SentNotificationRepository sent; private final JavaMailSender mail; private final MessageTemplates templates; private final Clock clock;
 public NotificationService(ProcessedEventRepository p,SentNotificationRepository s,JavaMailSender m,MessageTemplates t,Clock c){processed=p;sent=s;mail=m;templates=t;clock=c;}
 @Transactional public void handle(EventEnvelope e){if(e==null||e.eventId()==null||e.payload()==null||e.payload().claimantEmail()==null)return;if(processed.existsById(e.eventId()))return; if(!java.util.Set.of("ClaimSubmitted","ClaimAssigned","InfoRequested","InfoProvided","ClaimDecided").contains(e.eventType()))return; String subject=templates.subject(e),body=templates.body(e); SimpleMailMessage msg=new SimpleMailMessage();msg.setTo(e.payload().claimantEmail());msg.setSubject(subject);msg.setText(body);mail.send(msg);processed.save(new ProcessedEvent(e.eventId(),e.eventType(),Instant.now(clock)));sent.save(new SentNotification(e.eventId(),e.payload().claimantEmail(),subject,body,Instant.now(clock)));}
}
